import { Table, GuidColumn, BooleanColumn } from '@servicenow/sdk/core'

export const alm_hardware = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        kagami_csindex_enabled: true,
    },
    audit: true,
    extends: 'alm_asset',
    label: 'Hardware',
    name: 'alm_hardware',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        eligible_for_refresh: BooleanColumn({
            attributes: {
                no_text_index: true,
            },
            default: false,
            label: [
                {
                    hint: 'Is the asset eligible for refresh?',
                    label: 'Eligible for refresh',
                    plural: 'Eligible for refreshes',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
    },
})
